function merge(intervals) {
  intervals.sort((a, b) => a[0] - b[0]); // by start time
  const merged = [];
  for (const [start, end] of intervals) {
    const last = merged[merged.length - 1];
    if (last && start <= last[1]) { // overlaps (or touches) the last block
      last[1] = Math.max(last[1], end); // extend it
    } else {
      merged.push([start, end]); // gap: start a new block
    }
  }
  return merged;
}

def merge(intervals):
    intervals.sort(key=lambda x: x[0])  # by start time
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:  # overlaps the last block
            merged[-1][1] = max(merged[-1][1], end)  # extend it
        else:
            merged.append([start, end])  # gap: start a new block
    return merged

public int[][] merge(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0])); // by start
    List<int[]> merged = new ArrayList<>();
    for (int[] cur : intervals) {
        int[] last = merged.isEmpty() ? null : merged.get(merged.size() - 1);
        if (last != null && cur[0] <= last[1]) { // overlaps the last block
            last[1] = Math.max(last[1], cur[1]); // extend it
        } else {
            merged.add(new int[] { cur[0], cur[1] }); // gap: new block
        }
    }
    return merged.toArray(new int[0][]);
}

function insert(intervals, newInterval) {
  const result = [];
  let [start, end] = newInterval;
  let i = 0;
  const n = intervals.length;
  while (i < n && intervals[i][1] < start) { // ends before the new one starts
    result.push(intervals[i++]);
  }
  while (i < n && intervals[i][0] <= end) { // overlaps: absorb it
    start = Math.min(start, intervals[i][0]);
    end = Math.max(end, intervals[i][1]);
    i++;
  }
  result.push([start, end]); // the merged new interval
  while (i < n) { // starts after the new one ends
    result.push(intervals[i++]);
  }
  return result;
}

public int[][] insert(int[][] intervals, int[] newInterval) {
    List<int[]> result = new ArrayList<>();
    int start = newInterval[0], end = newInterval[1];
    int i = 0, n = intervals.length;
    while (i < n && intervals[i][1] < start) { // ends before the new one starts
        result.add(intervals[i++]);
    }
    while (i < n && intervals[i][0] <= end) { // overlaps: absorb it
        start = Math.min(start, intervals[i][0]);
        end = Math.max(end, intervals[i][1]);
        i++;
    }
    result.add(new int[] { start, end }); // the merged new interval
    while (i < n) { // starts after the new one ends
        result.add(intervals[i++]);
    }
    return result.toArray(new int[0][]);
}

function eraseOverlapIntervals(intervals) {
  intervals.sort((a, b) => a[1] - b[1]); // by END time
  let removed = 0;
  let lastEnd = -Infinity; // end of the last interval we kept
  for (const [start, end] of intervals) {
    if (start >= lastEnd) {
      lastEnd = end; // no overlap: keep it
    } else {
      removed++; // overlaps a kept interval that ends earlier: drop this one
    }
  }
  return removed;
}

