public int eraseOverlapIntervals(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1])); // by END time
    int removed = 0;
    long lastEnd = Long.MIN_VALUE; // end of the last interval we kept
    for (int[] cur : intervals) {
        if (cur[0] >= lastEnd) {
            lastEnd = cur[1]; // no overlap: keep it
        } else {
            removed++; // overlaps a kept interval that ends earlier: drop it
        }
    }
    return removed;
}

class MinHeap {
  constructor() { this.a = []; }
  size() { return this.a.length; }
  peek() { return this.a[0]; }
  push(x) {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0 && a[(i - 1) >> 1] > a[i]) { // sift up
      const p = (i - 1) >> 1;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop() {
    const a = this.a, top = a[0], last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      for (let i = 0; ;) { // sift down
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function minMeetingRooms(intervals) {
  intervals.sort((x, y) => x[0] - y[0]); // by start time
  const ends = new MinHeap(); // end times of meetings still holding a room
  for (const [start, end] of intervals) {
    if (ends.size() > 0 && ends.peek() <= start) {
      ends.pop(); // the earliest meeting is over: reuse its room
    }
    ends.push(end); // this meeting now holds a room until `end`
  }
  return ends.size(); // never shrinks, so it equals the peak number of rooms
}

import heapq

def min_meeting_rooms(intervals):
    intervals.sort(key=lambda x: x[0])  # by start time
    ends = []  # min-heap: end times of meetings still holding a room
    for start, end in intervals:
        if ends and ends[0] <= start:
            heapq.heapreplace(ends, end)  # earliest meeting is over: reuse its room
        else:
            heapq.heappush(ends, end)  # every room is busy: open a new one
    return len(ends)

public int minMeetingRooms(int[][] intervals) {
    Arrays.sort(intervals, (x, y) -> Integer.compare(x[0], y[0])); // by start
    PriorityQueue<Integer> ends = new PriorityQueue<>(); // end times of busy rooms
    for (int[] meeting : intervals) {
        if (!ends.isEmpty() && ends.peek() <= meeting[0]) {
            ends.poll(); // the earliest meeting is over: reuse its room
        }
        ends.offer(meeting[1]);
    }
    return ends.size(); // never shrinks, so it equals the peak number of rooms
}

function canJump(nums) {
  let reach = 0; // farthest index reachable so far
  for (let i = 0; i < nums.length; i++) {
    if (i > reach) return false; // stuck: index i can never be reached
    reach = Math.max(reach, i + nums[i]); // jumping from i extends the reach
    if (reach >= nums.length - 1) return true; // the last index is reachable
  }
  return true;
}

def can_jump(nums):
    reach = 0  # farthest index reachable so far
    for i, step in enumerate(nums):
        if i > reach:
            return False  # stuck: index i can never be reached
        reach = max(reach, i + step)  # jumping from i extends the reach
        if reach >= len(nums) - 1:
            return True  # the last index is reachable
    return True

public boolean canJump(int[] nums) {
    int reach = 0; // farthest index reachable so far
    for (int i = 0; i < nums.length; i++) {
        if (i > reach) return false; // stuck: index i can never be reached
        reach = Math.max(reach, i + nums[i]); // jumping from i extends the reach
        if (reach >= nums.length - 1) return true; // last index is reachable
    }
    return true;
}

function canCompleteCircuit(gas, cost) {
  let total = 0; // net gas over the whole loop
  let tank = 0;  // net gas since the current candidate start
  let start = 0;
  for (let i = 0; i < gas.length; i++) {
    const diff = gas[i] - cost[i];
    total += diff;
    tank += diff;
    if (tank < 0) { // cannot reach station i + 1 from start
      start = i + 1; // so no station in [start, i] can be the answer
      tank = 0;
    }
  }
  return total >= 0 ? start : -1;
}

public int canCompleteCircuit(int[] gas, int[] cost) {
