    int tank = 0;  // net gas since the current candidate start
    int start = 0;
    for (int i = 0; i < gas.length; i++) {
        int diff = gas[i] - cost[i];
        total += diff;
        tank += diff;
        if (tank < 0) { // cannot reach station i + 1 from start
            start = i + 1; // no station in [start, i] can be the answer
