}

function partitionLabels(s) {
  const last = new Map(); // char -> last index where it appears
  for (let i = 0; i < s.length; i++) last.set(s[i], i);
  const sizes = [];
  let start = 0, end = 0;
  for (let i = 0; i < s.length; i++) {
    end = Math.max(end, last.get(s[i])); // this part must reach s[i]'s last copy
    if (i === end) { // every char seen so far ends inside [start, end]
      sizes.push(end - start + 1);
      start = i + 1;
    }
  }
  return sizes;
}

public List<Integer> partitionLabels(String s) {
    int[] last = new int[26]; // letter -> last index where it appears
    for (int i = 0; i < s.length(); i++) last[s.charAt(i) - 'a'] = i;
    List<Integer> sizes = new ArrayList<>();
    int start = 0, end = 0;
    for (int i = 0; i < s.length(); i++) {
        end = Math.max(end, last[s.charAt(i) - 'a']); // reach its last copy
        if (i == end) { // every char seen so far ends inside [start, end]
            sizes.add(end - start + 1);
            start = i + 1;
        }
    }
    return sizes;
}

// Greedy: always take the largest coin that still fits — never reconsiders
function greedyCoins(coins, amount) {
  const sorted = [...coins].sort((a, b) => b - a);
  let count = 0;
  for (const coin of sorted) {
    count += Math.floor(amount / coin); // take as many as possible
    amount %= coin;
  }
  return amount === 0 ? count : -1;
}

// DP: for every amount, try every coin as the last one — O(amount · k)
function dpCoins(coins, amount) {
  const INF = amount + 1;
  const dp = new Array(amount + 1).fill(INF);
  dp[0] = 0;
  for (let a = 1; a <= amount; a++) {
    for (const coin of coins) {
      if (coin <= a) dp[a] = Math.min(dp[a], dp[a - coin] + 1);
    }
  }
  return dp[amount] === INF ? -1 : dp[amount];
}

