// Greedy: always take the largest coin that still fits — never reconsiders
int greedyCoins(int[] coins, int amount) {
    int[] sorted = coins.clone();
    Arrays.sort(sorted);
    int count = 0;
    for (int k = sorted.length - 1; k >= 0; k--) { // largest first
        count += amount / sorted[k];
        amount %= sorted[k];
    }
    return amount == 0 ? count : -1;
}

// DP: for every amount, try every coin as the last one — O(amount * k)
int dpCoins(int[] coins, int amount) {
    int INF = amount + 1;
    int[] dp = new int[amount + 1];
    Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int a = 1; a <= amount; a++) {
        for (int coin : coins) {
            if (coin <= a) dp[a] = Math.min(dp[a], dp[a - coin] + 1);
        }
    }
    return dp[amount] == INF ? -1 : dp[amount];
}

